import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class Solution {
    private Solution() {}

    public static final class Walkthrough {
        private final List<String> cards;
        private final boolean closed;

        private Walkthrough(List<String> cards, boolean closed) {
            this.cards = Collections.unmodifiableList(new ArrayList<String>(cards));
            this.closed = closed;
        }

        public List<String> getCards() {
            return cards;
        }

        public boolean isClosed() {
            return closed;
        }
    }

    public static Walkthrough openWalkthrough(List<String> cards) {
        validateCards(cards);
        return new Walkthrough(cards, false);
    }

    public static Walkthrough closeWalkthrough(Walkthrough walkthrough) {
        if (walkthrough == null) {
            throw new IllegalArgumentException("walkthrough is null");
        }
        return new Walkthrough(walkthrough.getCards(), true);
    }

    public static boolean allVisible(List<Boolean> visibility) {
        if (visibility == null) {
            throw new IllegalArgumentException("visibility is null");
        }
        boolean result = true;
        for (Boolean visible : visibility) {
            if (visible == null) {
                throw new IllegalArgumentException("null visibility");
            }
            if (!visible.booleanValue()) {
                result = false;
            }
        }
        return result;
    }

    private static void validateCards(List<String> cards) {
        if (cards == null) {
            throw new IllegalArgumentException("cards is null");
        }
        for (String card : cards) {
            if (card == null || card.isEmpty()) {
                throw new IllegalArgumentException("invalid card");
            }
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class Solution {
    private Solution() {}

    public static final class SortTrace {
        private final int[] sorted;
        private final List<int[]> passes;

        private SortTrace(int[] sorted, List<int[]> passes) {
            this.sorted = sorted.clone();
            this.passes = new ArrayList<int[]>();
            for (int[] pass : passes) {
                this.passes.add(pass.clone());
            }
        }

        public int[] getSorted() {
            return sorted.clone();
        }

        public List<int[]> getPasses() {
            List<int[]> copy = new ArrayList<int[]>();
            for (int[] pass : passes) {
                copy.add(pass.clone());
            }
            return Collections.unmodifiableList(copy);
        }
    }

    public static SortTrace traceDescending(int[] values) {
        if (values == null) {
            throw new IllegalArgumentException("values is null");
        }

        int[] work = values.clone();
        List<int[]> passes = new ArrayList<int[]>();
        if (work.length < 2) {
            return new SortTrace(work, passes);
        }

        int end = work.length - 1;
        while (true) {
            boolean swapped = false;
            for (int i = 0; i < end; i++) {
                if (work[i] < work[i + 1]) {
                    int temporary = work[i];
                    work[i] = work[i + 1];
                    work[i + 1] = temporary;
                    swapped = true;
                }
            }
            passes.add(work.clone());
            if (!swapped) {
                break;
            }
            if (end > 1) {
                end--;
            }
        }

        return new SortTrace(work, passes);
    }
}

def parse_sections(lines):
    try:
        pending = list(lines)
    except TypeError as exc:
        raise TypeError("lines must be iterable") from exc
    if any(not isinstance(line, str) for line in pending):
        raise TypeError("every line must be a string")

    result = []
    names = set()
    current = None

    for original in pending:
        stripped = original.strip()
        if not stripped or stripped.startswith("#"):
            continue

        if "=" in stripped:
            if current is None:
                raise ValueError("assignment appears before a section")
            key, value = stripped.split("=", 1)
            key = key.strip()
            value = value.strip()
            if not key:
                raise ValueError("assignment key is empty")
            current["values"][key] = value
            continue

        if stripped.startswith("[") or stripped.endswith("]"):
            if not (stripped.startswith("[") and stripped.endswith("]")):
                raise ValueError("malformed section header")
            name = stripped[1:-1]
            if not name or name != name.strip() or "[" in name or "]" in name:
                raise ValueError("malformed section header")
            if name in names:
                raise ValueError("duplicate section")
            current = {"name": name, "values": {}}
            result.append(current)
            names.add(name)
            continue

        if current is None:
            raise ValueError("assignment appears before a section")
        raise ValueError("assignment is missing equals sign")

    return result

class CommandRouter:
    def __init__(self):
        self._routes = []

    @staticmethod
    def _segments(value):
        if not isinstance(value, str) or not value.startswith("/"):
            raise ValueError("path must start with /")
        if value == "/":
            return []
        if value.endswith("/") or "//" in value:
            raise ValueError("path contains an empty segment")
        return value[1:].split("/")

    @staticmethod
    def _placeholder(segment):
        if not (segment.startswith("{") and segment.endswith("}")):
            return None
        body = segment[1:-1]
        wildcard = body.endswith("*")
        name = body[:-1] if wildcard else body
        if not name.isidentifier():
            raise ValueError("invalid placeholder")
        return name, wildcard

    def register(self, pattern, target):
        segments = self._segments(pattern)
        if not isinstance(target, str) or not target:
            raise ValueError("target must be a non-empty string")
        if any(route[0] == pattern for route in self._routes):
            raise ValueError("duplicate pattern")

        names = set()
        parsed = []
        score = []
        for index, segment in enumerate(segments):
            if "{" in segment or "}" in segment:
                placeholder = self._placeholder(segment)
                if placeholder is None:
                    raise ValueError("invalid pattern segment")
                name, wildcard = placeholder
                if name in names or (wildcard and index != len(segments) - 1):
                    raise ValueError("invalid placeholder")
                names.add(name)
                parsed.append((name, wildcard))
                score.append(0 if wildcard else 1)
            else:
                parsed.append(None)
                score.append(2)
        self._routes.append((pattern, target, segments, parsed, tuple(score), len(self._routes)))

    def resolve(self, path):
        parts = self._segments(path)
        matches = []
        for _, target, pattern, parsed, score, order in self._routes:
            params = {}
            cursor = 0
            valid = True
            for segment, placeholder in zip(pattern, parsed):
                if placeholder is not None and placeholder[1]:
                    if cursor >= len(parts):
                        valid = False
                        break
                    params[placeholder[0]] = "/".join(parts[cursor:])
                    cursor = len(parts)
                elif cursor >= len(parts):
                    valid = False
                    break
                elif placeholder is not None:
                    params[placeholder[0]] = parts[cursor]
                    cursor += 1
                elif segment == parts[cursor]:
                    cursor += 1
                else:
                    valid = False
                    break
            if valid and cursor == len(parts):
                matches.append((score, -order, target, params))
        if not matches:
            raise KeyError(path)
        _, _, target, params = max(matches, key=lambda item: (item[0], item[1]))
        return target, dict(params)


def make_inventory_router():
    router = CommandRouter()
    router.register("/items", "item_list")
    router.register("/items/{code}", "item_detail")
    router.register("/items/new", "item_create")
    router.register("/makers/new", "maker_create")
    router.register("/rooms/new", "room_create")
    router.register("/regions/new", "region_create")
    router.register("/assets/{path*}", "asset")
    return router

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum FieldError {
    EmptyName,
    Malformed,
    Duplicate,
}

pub fn read_tagged_field(input: &str, name: &str) -> Result<Option<String>, FieldError> {
    if name.is_empty() {
        return Err(FieldError::EmptyName);
    }

    let bytes = input.as_bytes();
    let mut pos = 0usize;
    let mut result = None;
    let mut duplicate = false;

    while pos < bytes.len() {
        if bytes[pos] != b'[' {
            pos += 1;
            continue;
        }

        let next = bytes.get(pos + 1).copied();
        if next == Some(b'/') {
            return Err(FieldError::Malformed);
        }
        if !next.map_or(false, |byte| byte.is_ascii_alphabetic()) {
            pos += 1;
            continue;
        }

        let open_end = input[pos + 1..]
            .find(']')
            .map(|offset| pos + 1 + offset)
            .ok_or(FieldError::Malformed)?;
        let open_name = &input[pos + 1..open_end];
        let close = format!("[/{open_name}]");
        let content_start = open_end + 1;
        let relative_end = input[content_start..]
            .find(&close)
            .ok_or(FieldError::Malformed)?;
        let content_end = content_start + relative_end;
        let content = &input[content_start..content_end];

        if content.as_bytes().windows(2).any(|window| {
            window[0] == b'['
                && (window[1] == b'/' || window[1].is_ascii_alphabetic())
        }) {
            return Err(FieldError::Malformed);
        }

        if open_name == name {
            if result.is_some() {
                duplicate = true;
            } else {
                result = Some(content.to_owned());
            }
        }
        pos = content_end + close.len();
    }

    if duplicate {
        Err(FieldError::Duplicate)
    } else {
        Ok(result)
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Decision {
    Permit,
    Reject,
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum RequestKind {
    Code,
    Media,
    Style,
}

pub struct Rule {
    pub host_suffix: String,
    pub kind: Option<RequestKind>,
    pub decision: Decision,
}

pub struct Policy {
    rules: Vec<Rule>,
}

impl Policy {
    pub fn new(rules: Vec<Rule>) -> Result<Policy, String> {
        if rules.iter().any(|rule| !valid_host(&rule.host_suffix)) {
            return Err("invalid host suffix".to_string());
        }
        Ok(Policy { rules })
    }

    pub fn evaluate(&self, host: &str, kind: RequestKind) -> Decision {
        if !valid_host(host) {
            return Decision::Permit;
        }

        for rule in &self.rules {
            let host_matches = host == rule.host_suffix
                || host
                    .strip_suffix(&rule.host_suffix)
                    .map_or(false, |prefix| prefix.ends_with('.'));
            let kind_matches = rule.kind.is_none() || rule.kind == Some(kind);
            if host_matches && kind_matches {
                return rule.decision;
            }
        }

        Decision::Permit
    }
}

fn valid_host(value: &str) -> bool {
    !value.is_empty()
        && value
            .bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'.' || b == b'-')
}
